# xorBits — ../src/contract.lawspec:1110
def xor_bits(a, b, bit):
    if ((bit <= 0) or (a < 0)) or (b < 0):
        return 0
    else:
        if lsf_quot(a, bit) != lsf_quot(b, bit):
            value = bit
        else:
            value = 0
        return value + xor_bits(lsf_rem(a, bit), lsf_rem(b, bit), lsf_quot(bit, 2))


