# From the dynamic value of a 25c3f950e3431c91ceedb89b1adb06da7d2d7d20322b03e1f64f63418e45d7e3.
def from_control_entry_details(v):
    if (
        v.tag
        == "lawspec::structural::record::25c3f950e3431c91ceedb89b1adb06da7d2d7d20322b03e1f64f63418e45d7e3::Record"
    ):
        return (v.fields[0], v.fields[1], v.fields[2])
    raise ValueError("expected ControlEntryDetails, found " + v.tag)


# From the dynamic value of a 71ddc692ac9521d9d1f5404c57337ef3fb4c795693ec774d5443d945ea34e0be.
def from_data_entry_details(v):
    if (
        v.tag
        == "lawspec::structural::record::71ddc692ac9521d9d1f5404c57337ef3fb4c795693ec774d5443d945ea34e0be::Record"
    ):
        return (v.fields[0], from_record(v.fields[1]), v.fields[2], v.fields[3])
    raise ValueError("expected DataEntryDetails, found " + v.tag)


# From the dynamic value of a Header.
def from_header(v):
    if v.tag == "lawtwin.kafka.model::type::Header::Header":
        return (v.fields[0], from_maybe_bytes(v.fields[1]))
    raise ValueError("expected Header, found " + v.tag)


# From the dynamic value of a LastSend.
def from_last_send(v):
    if v.tag == "lawtwin.kafka::type::LastSend::LastSend":
        return (
            from_topic_partition(v.fields[0]),
            from_maybe_producer_tag(v.fields[1]),
            from_list_record(v.fields[2]),
        )
    raise ValueError("expected LastSend, found " + v.tag)


