# From the native value of a PartitionChoice.
def fromnative_partition_choice(n):
    kind = type(n)
    if kind is data.PartitionChoiceToPartition:
        return (1, n.value)
    if kind is data.PartitionChoiceByKey:
        return (0,)
    raise TypeError("expected PartitionChoice")


